import{_ as o}from"./chunks/photocurves_icon_rounded_256x256.DpwwrzEQ.js";import{_ as t}from"./chunks/google-play-badge.BbBgb8nI.js";import{_ as a,o as r,c as s,a2 as i}from"./chunks/framework.vOTwFLKw.js";const n="/images/microsoft-store-badge.svg",c="/images/apple-store-badge.png",l="/images/mac-store-badge.png",d="/assets/Screenshot_1_small.DVbDZU_K.jpg",p="/assets/Screenshot_6_small.DAqsVYkt.jpg",h="/assets/Screenshot_4_small.EHNgOxBp.jpg",u="/assets/Screenshot_2_small.DcGhvq6W.jpg",g="/assets/PhotoCurvesMac-2.f5Pvx8eH.png",x=JSON.parse('{"title":"Photo Curves Color Grading App","description":"Edit photos with RGB, CMYK and LAB curves, color wheels, layer masks and HSL tools. Create custom 3D LUT files on Android, iOS, macOS, Windows or the web.","frontmatter":{"title":"Photo Curves Color Grading App","description":"Edit photos with RGB, CMYK and LAB curves, color wheels, layer masks and HSL tools. Create custom 3D LUT files on Android, iOS, macOS, Windows or the web.","permalink":"/photocurves/","canonicalUrl":"https://curvednebula.com/photocurves/","meta":[{"name":"keywords","content":"Photo Curves, color grading app, photo editor, RAW photo editor, Windows photo editor, 3D LUT creator, RGB curves, color wheels, photo color correction"},{"property":"og:title","content":"Photo Curves Color Grading App and 3D LUT Creator"},{"property":"og:description","content":"Color correct photos on Android, iOS, macOS and Windows, create cinematic looks and export custom 3D LUTs with professional curves, color wheels and layer masks."},{"property":"og:type","content":"website"},{"property":"og:url","content":"https://curvednebula.com/photocurves/"},{"property":"og:image","content":"https://curvednebula.com/images/photocurves_icon_rounded_256x256.png"},{"name":"twitter:card","content":"summary"}],"aside":false},"headers":[],"relativePath":"photocurves/index.md","filePath":"photocurves/index.md"}'),m={name:"photocurves/index.md"};function v(f,e,b,C,_,P){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="photo-curves-color-grading-app" tabindex="-1">Photo Curves Color Grading App <a class="header-anchor" href="#photo-curves-color-grading-app" aria-label="Permalink to &quot;Photo Curves Color Grading App&quot;">​</a></h1><img src="'+o+'" alt="Photo Curves color grading app icon" height="100"><p><strong>Photo Curves</strong> is a tool for detailed color correction and creative color grading for photos and videos. The app is available for Android, iPhone, iPad, macOS, and Windows.</p><h2 id="download-photo-curves-or-edit-online" tabindex="-1">Download Photo Curves or edit online <a class="header-anchor" href="#download-photo-curves-or-edit-online" aria-label="Permalink to &quot;Download Photo Curves or edit online&quot;">​</a></h2><div class="store-badges" aria-label="Download Photo Curves"><a href="https://play.google.com/store/apps/details?id=com.foreachi.photocurves"><img src="'+t+'" alt="Get Photo Curves on Google Play"></a><a href="https://apps.microsoft.com/detail/9mt3t7393m6p"><img src="'+n+'" alt="Get Photo Curves for Windows from Microsoft"></a><a href="https://apps.apple.com/app/id1606599231#?platform=iphone"><img src="'+c+'" alt="Get Photo Curves for iPhone and iPad on the App Store"></a><a href="https://apps.apple.com/app/id1638484562"><img src="'+l+'" alt="Get Photo Curves for macOS on the Mac App Store"></a></div><p><a href="https://photocurves.curvednebula.com" target="_blank" rel="noreferrer">Use Photo Curves Online</a> for free photo editing in a web browser.</p><h2 id="supported-image-and-video-formats" tabindex="-1">Supported image and video formats <a class="header-anchor" href="#supported-image-and-video-formats" aria-label="Permalink to &quot;Supported image and video formats&quot;">​</a></h2><p>Photo Curves supports major popular image and video formats such as JPEG, PNG, HEIC/HEIF, WebP, and BMP, including RAW files: DNG, CR2, CR3, NEF, ARW, RAF, ORF, and RW2.</p><p>Video support includes popular formats such as MP4, MOV, WebM, MKV, and AVI. Exact format and codec availability may vary by operating system. Finished photos can be exported as JPEG or PNG, videos - as MP4.</p><h2 id="create-custom-3d-luts-and-editable-presets" tabindex="-1">Create custom 3D LUTs and editable presets <a class="header-anchor" href="#create-custom-3d-luts-and-editable-presets" aria-label="Permalink to &quot;Create custom 3D LUTs and editable presets&quot;">​</a></h2><p>Create your own 3D LUTs and export them as <code>.cube</code> files for use in compatible photo and video software. Photo Curves also includes example presets that remain fully editable, unlike a flattened LUT.</p><p>Use the editor to correct or enhance colors, adjust white balance, replace color ranges, shift hue, or develop stylized looks such as cinematic orange and teal.</p><p><img src="'+d+'" alt="Photo Curves mobile color grading editor" width="142"><img src="'+p+'" alt="Editing photo colors with curves in Photo Curves" width="142"><img src="'+h+'" alt="Photo Curves selective color adjustment controls" width="142"><img src="'+u+'" alt="Photo Curves color correction interface" width="142"></p><img src="'+g+'" alt="Photo Curves color grading photo editor on macOS" width="600"><h2 id="color-grading-tools" tabindex="-1">Color grading tools <a class="header-anchor" href="#color-grading-tools" aria-label="Permalink to &quot;Color grading tools&quot;">​</a></h2><ul><li><p><strong>Basic controls</strong> — adjust brightness, contrast, shadows, highlights, and saturation.</p></li><li><p><strong>Color wheels</strong> — mix color tones into shadows, midtones, or highlights.</p></li><li><p><strong>Layer masks</strong> — create adjustment layers and draw masks to apply color grading effects to selected parts of an image.</p></li><li><p><strong>RGB curves</strong> — adjust the red, green, and blue channels of the RGB color space.</p></li><li><p><strong>CMYK curves</strong> — adjust the cyan, magenta, yellow, and key channels of the CMYK color space.</p></li><li><p><strong>LAB curves</strong> — separate lightness from color information for additional creative control.</p></li><li><p><strong>Hue vs saturation curve</strong> — select a hue range and change its saturation, such as creating a black-and-white image that preserves one color.</p></li><li><p><strong>Hue vs hue curve</strong> — select a hue range and replace its color, such as changing a blue sky to purple or green grass to orange.</p></li><li><p><strong>Hue vs luma curve</strong> — select a hue range and change its brightness.</p></li><li><p><strong>Luma vs saturation curve</strong> — adjust saturation independently in shadows, midtones, and highlights.</p></li><li><p><strong>Luma vs hue curve</strong> — shift the hue of shadows, midtones, or highlights.</p></li><li><p><strong>Saturation vs saturation curve</strong> — boost muted colors or reduce oversaturated colors for a more even result.</p></li></ul><h2 id="color-correction-and-creative-editing" tabindex="-1">Color correction and creative editing <a class="header-anchor" href="#color-correction-and-creative-editing" aria-label="Permalink to &quot;Color correction and creative editing&quot;">​</a></h2><p>Photo Curves can handle both corrective and creative workflows. Use curves and basic controls to balance exposure and color, then add targeted adjustments with hue curves, color wheels, and masks. Because the adjustments remain editable, you can refine a look before exporting the finished image or LUT.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h2><h3 id="can-photo-curves-create-cube-lut-files" tabindex="-1">Can Photo Curves create <code>.cube</code> LUT files? <a class="header-anchor" href="#can-photo-curves-create-cube-lut-files" aria-label="Permalink to &quot;Can Photo Curves create `.cube` LUT files?&quot;">​</a></h3><p>Yes. You can export your color grading preset as a standard <code>.cube</code> 3D LUT file for compatible applications.</p><h3 id="what-is-the-difference-between-a-preset-and-a-lut" tabindex="-1">What is the difference between a preset and a LUT? <a class="header-anchor" href="#what-is-the-difference-between-a-preset-and-a-lut" aria-label="Permalink to &quot;What is the difference between a preset and a LUT?&quot;">​</a></h3><p>A LUT applies a fixed color transformation. Photo Curves presets retain their individual adjustment settings, so curves, color wheels, and other controls can be edited after a preset is applied.</p>',23)])])}const q=a(m,[["render",v]]);export{x as __pageData,q as default};
